const zscBolt = (cx, cy, r) => {
  const o = oval(cx, cy, r, r);
  flat(o, WASH.sky);
  const sp = [];
  for (let i = 0; i <= 40; i++) { const t = i / 40 * Math.PI * 5.5, rr = r * (.25 + .6 * i / 40); sp.push([cx + rr * Math.cos(t), cy + rr * Math.sin(t)]); }
  ink(smooth(sp), .7, {col: mixC(WASH.sky, TONE, .4), over: 0});
  flat(oval(cx, cy, r * .2, r * .2), '#efe7d6');
  lid(o, 1.2);
};
