const quadStack = (x, base, h) => {
  const w = 34, t = base - h;
  const body = [[x - w / 2, t], [x + w / 2, t], [x + w / 2, base], [x - w / 2, base]];
  flat(body, WASH.gold);
  const marks = [];
  for (let y = base - 4; y > t + 2; y -= 4) marks.push([[x - w / 2, y], [x + w / 2, y]]);
  rule(marks, mixC(WASH.gold, TONE, .35), .6, .7);
  lid(body, 1.15);
  const top = oval(x, t, w / 2, 3.5);
  flat(top, mixC(WASH.gold, PAPER, .4));
  lid(top, 1.1);
};

const quadArrow = (a, b) => {
  ink([a, b], 1.1, {over: 0});
  ink([[b[0] - 6, b[1] - 4], b, [b[0] - 6, b[1] + 4]], 1.1, {over: 0});
};

card({id:'quad', name:'Quadrant', of:'elasticity and the direction of revenue', note:'Left stack is revenue before the price change, right stack after. Taller means more revenue.',
  draw(){
    const D = [
      {c:0, r:0, rise:true,  cap:'price effect wins', note:'Inelastic demand, price up: revenue rises. Buyers cut quantity by a smaller percent than the price rises'},
      {c:1, r:0, rise:false, cap:'price effect wins', note:'Inelastic demand, price down: revenue falls. Buyers add a smaller percent of quantity than the price drops'},
      {c:0, r:1, rise:false, cap:'quantity effect wins', red:true, note:'Elastic demand, price up: revenue falls. The quantity lost is the larger percent'},
      {c:1, r:1, rise:true,  cap:'quantity effect wins', note:'Elastic demand, price down: revenue rises. The quantity gained is the larger percent'}
    ];
    const X0 = 100, Y0 = 68, CW = 193, CH = 160, GAP = 4;
    TXC(X0 + CW / 2, 50, 'price up', {size: 15, cap: true});
    TXC(X0 + CW + GAP + CW / 2, 50, 'price down', {size: 15, cap: true});
    TXC(52, Y0 + CH / 2, 'Inelastic\ndemand\nbelow 1', {size: 14});
    TXC(52, Y0 + CH + GAP + CH / 2, 'Elastic\ndemand\nabove 1', {size: 14});
    for (const d of D) {
      const x = X0 + d.c * (CW + GAP), y = Y0 + d.r * (CH + GAP), cx = x + CW / 2, base = y + 118;
      const frame = rrect(x, y, CW, CH, 8);
      wash(frame, d.rise ? WASH.sage : WASH.rose);
      lid(frame, 1.1);
      PT(d.note, () => {
        TXC(cx, y + 22, d.rise ? 'Revenue rises' : 'Revenue falls', {size: 15, col: d.red ? RED : INK});
        const tray = rrect(cx - 80, base, 160, 12, 5);
        flat(tray, WASH.wood);
        lid(tray, 1.2);
        const hA = d.rise ? 40 : 64, hB = d.rise ? 64 : 40;
        quadStack(cx - 55, base, hA);
        quadStack(cx + 55, base, hB);
        const ay = base - 18;
        if (d.red) { AR([cx - 24, ay], [cx + 24, ay]); } else { quadArrow([cx - 24, ay], [cx + 24, ay]); }
        TXC(cx, y + 146, d.cap, {size: 13.5, col: LN});
      }, {lift: [0, -4]});
    }
  }});

